   AND DEPT_CD = #{DEPT_CD}

mapper.insert:
INSERT INTO MSTMENUGDPT (  --부서별 메뉴 그룹 할당정보
	  COMPID
	, MENUGROUPID
	, DEPT_CD
	, CREATEDATE
	, UPDATEUSER
)
SELECT #{COMPKY}
	 , #{MENUGROUPID}
	 , #{DEPT_CD}
	 , SYSDATE
	 , #{SES_USER_ID}
  FROM DUAL
 WHERE NOT EXISTS (
 	SELECT 1 FROM MSTMENUGDPT  --부서별 메뉴 그룹 할당정보
	 WHERE COMPID = #{COMPKY}
	   AND MENUGROUPID = #{MENUGROUPID}
	   AND DEPT_CD = #{DEPT_CD}
 )

