SELECT SL.LOGDAT , SL.LOGTIM , SL.LOGTYP , NVL((SELECT CDESC1 FROM CMCDV WHERE CMCDKY = 'LOGTYP' AND CMCDVL = LOGTYP),' ') AS "LOGTNM" , SL.LOGUSR , NVL(US.NMLAST,' ') AS "NMLAST" , SL.LOGIPA , SL.REMARK FROM SYSLG SL INNER JOIN USRMA US ON US.USERID = SL.LOGUSR WHERE 1 = 1 AND LOGTYP IN (SELECT CMCDVL FROM CMCDV WHERE CMCDKY = 'LOGTYP' AND USARG1 = 'LG01')
AND SL.LOGTYP = #{LOGTYP}
${RANGE_SQL}

SELECT SL.LOGDAT , SL.LOGTIM , SL.LOGTYP , NVL((SELECT CDESC1 FROM CMCDV WHERE CMCDKY = 'LOGTYP' AND CMCDVL = SL.LOGTYP),' ') AS "LOGTNM" , SL.LOGUSR , NVL(US.NMLAST,' ') AS "NMLAST" , SL.LOGIPA , SL.PROGID , NVL((SELECT LABEL FROM SYSLABEL WHERE LANGCODE = 'KR' AND LABELGID = 'MENU' AND LABELID = SL.PROGID),' ') AS PROGNM , SL.REMARK FROM SYSLG SL INNER JOIN USRMA US ON US.USERID = SL.LOGUSR WHERE 1 = 1 AND LOGTYP IN (SELECT CMCDVL FROM CMCDV WHERE CMCDKY = 'LOGTYP' AND USARG1 = 'LG02')
AND SL.LOGTYP = #{LOGTYP}
${RANGE_SQL}

SELECT SL.LOGDAT , SL.LOGTIM , SL.LOGTYP , NVL((SELECT CDESC1 FROM CMCDV WHERE CMCDKY = 'LOGTYP' AND CMCDVL = SL.LOGTYP),' ') AS "LOGTNM" , SL.LOGUSR , NVL(US.NMLAST,' ') AS "NMLAST" , SL.LOGIPA , SL.PROGID , NVL((SELECT LABEL FROM SYSLABEL WHERE LANGCODE = 'KR' AND LABELGID = 'MENU' AND LABELID = SL.PROGID),' ') AS PROGNM , SL.REMARK FROM SYSLG SL INNER JOIN USRMA US ON US.USERID = SL.LOGUSR WHERE 1 = 1 AND LOGTYP IN (SELECT CMCDVL FROM CMCDV WHERE CMCDKY = 'LOGTYP' AND USARG1 = 'LG03')
AND SL.LOGTYP = #{LOGTYP}
${RANGE_SQL}

