INSERT INTO SYSLG
(
    LOGDAT, LOGTIM, LOGTYP, LOGUSR, LOGIPA, PROGID
  , CREDAT, CRETIM, CREUSR, LMODAT, LMOTIM, LMOUSR
)
VALUES(
          TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), 'PGOP', #{USERID}


		,' '


		,#{SES_USER_IP}


		,  #{PROGID}
        , TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), #{USERID}
        , TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), #{USERID}
      )

MERGE INTO 
	SYSLG
USING DUAL
	ON (
		LOGDAT = TO_CHAR(SYSDATE,'YYYYMMDD')
		AND LOGTIM = TO_CHAR(SYSDATE,'HH24MISS')
		AND LOGTYP = 'PGSC'
		AND LOGUSR = #{SES_USER_ID}
		AND PROGID = #{PROGID}
	)
	WHEN MATCHED THEN
		UPDATE SET
				LMODAT = TO_CHAR(SYSDATE,'YYYYMMDD'),
				LMOTIM = TO_CHAR(SYSDATE,'HH24MISS'),
				LMOUSR = #{SES_USER_ID}
		DELETE WHERE (
			LOGDAT = TO_CHAR(SYSDATE,'YYYYMMDD')
		AND LOGTIM = TO_CHAR(SYSDATE,'HH24MISS')
		AND LOGTYP = 'PGSC'
		AND LOGUSR = #{SES_USER_ID}
		AND PROGID = #{PROGID}
		)
	WHEN NOT MATCHED THEN
		INSERT
		(
		    LOGDAT, LOGTIM, LOGTYP, LOGUSR, LOGIPA, PROGID
		  , CREDAT, CRETIM, CREUSR
		  , LMODAT, LMOTIM, LMOUSR
		)
		VALUES(
		          TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), 'PGSC', #{SES_USER_ID}


				,' '


				,#{SES_USER_IP}


			  , #{PROGID}
		        , TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), #{SES_USER_ID}
		        , TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), #{SES_USER_ID}
		      )

